1	/* Tier-2 C-level fixture: 16x16x16 GEMM (2-phase: QEMU1 -> vsim).
2	 *
3	 *   QEMU 1: init_matrices -- fills A and B with deterministic patterns.
4	 *   vsim:   matmul_kernel -- pure C = A * B, no syscalls (phase-2 rule).
5	 *           C is written to .bss inside the ROI; the exit_vsim "memory"
6	 *           clobber anchors the stores so the kernel is not eliminated.
7	 *           vsim drains at the exit marker and exits 200.
8	 *
9	 * (The old phase-3 QEMU2 print + independent re-verify was removed with the
10	 * QEMU2 leg; the fixture now validates that the GEMM kernel runs and drains.)
11	 *
12	 * Cross-phase memory survival
13	 *   Matrices sit in .bss. The "no redundant ELF reload" rule keeps phase-1
14	 *   .bss writes intact through the shared memory-backend-file.
15	 */
16	#include "runtime/rt_c_helpers.h"
17	
18	#include <stdint.h>
19	
20	#define N 16
21	
22	static int32_t A[N * N];
23	static int32_t B[N * N];
24	static int32_t C[N * N];
25	
26	#define AT(M, i, j) ((M)[(i) *N + (j)])
27	
28	static void init_matrices(void)
29	{
30	  for (int i = 0; i < N; i++) {
31	    for (int j = 0; j < N; j++) {
32	      AT(A, i, j) = (int32_t) ((i + j) % 7);
33	      AT(B, i, j) = (int32_t) ((i * 3 + j) % 5);
34	    }
35	  }
36	}
37	
38	static void matmul_kernel(void)
39	{
40	  for (int i = 0; i < N; i++) {
41	    for (int j = 0; j < N; j++) {
42	      int32_t s = 0;
43	      for (int k = 0; k < N; k++) {
44	        s += AT(A, i, k) * AT(B, k, j);
45	      }
46	      AT(C, i, j) = s;
47	    }
48	  }
49	}
50	
51	int main(void)
52	{
53	  /* Phase 1 (QEMU 1): seed inputs. */
54	  init_matrices();
55	
56	  enter_vsim();
57	
58	  /* Phase 2 (vsim): GEMM kernel only. No syscalls. */
59	  matmul_kernel();
60	
61	  exit_vsim();
62	
63	  return 0;
64	}
