23	template<typename Trigger, typename Observer = NullObserver>
24	class HandoffController
25	{
26	public:
27	  HandoffController(Trigger trigger, DmiBus& bus)
28	      : trigger_{std::move(trigger)}, drain_{bus}
29	  {}
30	
31	  HandoffController(Trigger trigger, DmiBus& bus, Observer observer)
32	      : trigger_{std::move(trigger)},
33	        drain_{bus},
34	        observer_{std::move(observer)}
35	  {}
36	
37	  // Snapshot of the QEMU 1 input state. When set, drain merges FP/CSR/V
38	  // fields from the snapshot into the freshly drained GPRs+PC, avoiding
39	  // a per-field DM Abstract Command on every handoff.
40	  void set_passthrough_input(hybrid_state_v1 input)
41	  {
42	    passthrough_ = input;
43	  }
44	
45	  // Read-only view of the underlying trigger. Used by the ROI kanata-gate
46	  // derivation, which needs to read scanned EXIT PCs without consuming them.
47	  auto trigger() const -> const Trigger& { return trigger_; }
48	
49	  // Read-only view of the observer slot. F16 (StateDrain) reads the warmup
50	  // snapshot from here when copying into the ABI struct.
51	  auto observer() const -> const Observer& { return observer_; }
52	  auto observer() -> Observer& { return observer_; }
53	
54	  auto on_retire(uint64_t pc) -> std::optional<hybrid_state_v1>
55	  {
56	    if constexpr (requires { trigger_.observe_commit(); }) {
57	      trigger_.observe_commit();
58	    }
59	    if constexpr (requires { observer_.observe_commit(); }) {
60	      observer_.observe_commit();
61	    }
62	    const auto hit = trigger_.lookup(pc);
63	    if (!hit) return std::nullopt;
64	
65	    // Only EXIT drains; entry is QEMU's job, vsim ignores ENTER.
66	    if (hit->kind != HYBRID_HANDOFF_EXIT) return std::nullopt;
67	    // F16: push warmup snapshot into the drain right before it runs so the
68	    // returned state file carries mcycle_at_measure_start / minstret_at_measure_start.
69	    // The if-constexpr branch compiles away for NullObserver (no accessors).
70	    if constexpr (requires { observer_.mcycle_at_measure_start(); }) {
71	      drain_.set_warmup_snapshot(observer_.mcycle_at_measure_start(),
72	                                 observer_.minstret_at_measure_start());
73	    }
74	    if (passthrough_) return drain_.drain_with_passthrough(*passthrough_);
75	    return drain_.drain();
76	  }
77	
78	private:
79	  Trigger trigger_;
80	  StateDrain drain_;
81	  Observer observer_{};
82	  std::optional<hybrid_state_v1> passthrough_;
83	};
84	
85	// CTAD: the old `HandoffController(trigger, bus)` call sites must still
86	// deduce `Observer = NullObserver`. The default-arg form of CTAD cannot
87	// see template defaults, so spell them out as deduction guides.
88	template<typename Trigger>
89	HandoffController(Trigger, DmiBus&)
90	  -> HandoffController<Trigger, NullObserver>;
91	
92	template<typename Trigger, typename Observer>
93	HandoffController(Trigger, DmiBus&, Observer)
94	  -> HandoffController<Trigger, Observer>;
95	
96	}  // namespace hybrid
