78	// icount-trigger mode: when icount_target is non-zero (set via plugin arg
79	// `icount=N`), every translated insn gets an exec callback that bumps a
80	// per-vcpu counter; on threshold-cross the drain fires at that insn
81	// boundary. Coexists with CSR/PC modes - either trigger can win.
82	static uint64_t icount_target;
83	static int icount_mode;
84	
85	// BBV-emit mode (SimPoint profile): when bbv_mode is set (plugin args
86	// `bbv_out=PATH,slice=N`), every translated insn gets an exec callback
87	// that ticks a global BBV counter; one .bb row per N retired insns is
88	// flushed to PATH. Coexists with the drain triggers - independently
89	// registered before icount so that on co-firing (icount target == slice
90	// multiple) the slice row is emitted before exit(200).
91	static BbvEmit *bbv_emit;
92	static char    *bbv_out_path;
93	static uint64_t bbv_slice_target;
94	static int      bbv_mode;
95	
96	// Slice-consume mode (SimPoint replay; F11): when slice_consume_mode is
97	// set (plugin args `slice=N,slice_at=K`), the plugin counts slice
98	// boundaries (one boundary per N retired insns) and drains at the end
99	// of slice index K (0-based). With K=2 and slice=1000, drain fires at
100	// insn 3000 - the boundary that closes the third slice. The orchestrator
101	// chains one invocation per SimPoint cluster-representative slice idx.
102	// Shares the `slice=` parameter with BBV-emit; works independently of
103	// whether `bbv_out=` is also set.
104	static uint64_t slice_at_target;
105	static int      slice_consume_mode;
106	static uint64_t slice_consume_acc;
107	static uint64_t slice_consume_idx;
108	
109	// Drain-at-exit mode (F14): when drain_at_exit_mode is set (plugin arg
110	// `drain_at_exit=1`), the plugin registers a per-insn exec callback that
111	// bumps `atexit_insn_count`, and a `qemu_plugin_register_atexit_cb` that
112	// drains state on natural program exit (e.g. semihosting EXIT). The
113	// atexit callback overrides s.minstret with the plugin counter so the
114	// caller (./hsim estimate --icount 0) gets a true retired-insn count
115	// independent of QEMU's PMU semantics (which can return host ticks on
116	// system-mode without `-icount`). `drained_already` suppresses the
117	// atexit path if any other trigger (CSR/PC/icount/slice) drained first.
118	static int      drain_at_exit_mode;
119	static volatile int drained_already;
120	static uint64_t atexit_insn_count;
