122	static struct qemu_plugin_register *find_reg(GArray *regs, const char *name)
123	{
124	    for (guint i = 0; i < regs->len; i++) {
125	        qemu_plugin_reg_descriptor *rd =
126	            &g_array_index(regs, qemu_plugin_reg_descriptor, i);
127	        if (g_ascii_strcasecmp(rd->name, name) == 0) {
128	            return rd->handle;
129	        }
130	    }
131	    return NULL;
132	}
