343	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
344	// as the vsim resume point, and exit 200.
345	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
346	{
347	    // F14: suppress the atexit drain path now that we have a real trigger.
348	    drained_already = 1;
349	    drain_state_to_file(vcpu_idx, resume_pc, 0);
350	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
351	    // Distinguishes drain from workload completion (0) so the orchestrator
352	    // can decide the next spawn.
353	    exit(200);
354	}
355	
356	// Marker sites. The marker is an architectural NOP, so the pre-execution
357	// state equals the post-retire state and the window resumes AFTER it
358	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
359	// the exec callback can lag the actual current insn when V instructions
360	// retire just before the trigger -- TCG defers PC writes for performance).
361	static void on_handoff(unsigned int vcpu_idx, void *udata)
362	{
363	    const HandoffSite *site = (const HandoffSite *) udata;
364	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
365	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
366	}
367	
368	// pc/icount/slice boundary sites. Exec callbacks fire BEFORE the insn
369	// executes, and the boundary insn is real user code (unlike a marker NOP):
370	// the drained state must resume AT the boundary so the insn executes inside
371	// the vsim window rather than on neither leg. (Skipping it corrupts the
372	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
373	// set and the first vector op of the window faults.)
374	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
375	{
376	    const HandoffSite *site = (const HandoffSite *) udata;
377	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
378	    handoff_drain(vcpu_idx, site->vaddr);
379	}
380	
381	// F14: per-insn tick. Increments a global counter every retired insn so the
382	// drain-at-exit path can report a true retired-insn total (independent of
383	// QEMU's PMU semantics).
384	static void on_count_tick(unsigned int vcpu_idx, void *udata)
385	{
386	    (void) vcpu_idx;
387	    (void) udata;
388	    atexit_insn_count++;
389	}
390	
391	// F14: atexit drain. Fires when QEMU exits naturally (e.g. guest semihosting
392	// EXIT). The semihosting EXIT runs on the vCPU thread, so current_cpu is
393	// still set and qemu_plugin_read_register works. If any other trigger
394	// already drained, return immediately (drained_already guards against
395	// double drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4;
396	// use _exit() to skip the rest of the atexit chain.
397	static void on_atexit(qemu_plugin_id_t id, void *udata)
398	{
399	    (void) id;
400	    (void) udata;
401	    if (drained_already) return;
402	    if (!drain_at_exit_mode) return;
403	    // pc=0 is a positive marker that the atexit path drained (no trigger).
404	    drain_state_to_file(0, 0, atexit_insn_count);
405	    fflush(stderr);
406	    _exit(200);
407	}
408	
409	// Per-insn tick for icount mode. udata is the per-insn HandoffSite
410	// pre-allocated at translation time, so on_handoff's compute_handoff_pc
411	// returns the lag-free post-trigger PC (same property as the CSR path).
412	static void on_icount_tick(unsigned int vcpu_idx, void *udata)
413	{
414	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
415	    if (++v->icount_retired < icount_target) return;
416	    on_handoff_boundary(vcpu_idx, udata);
417	}
418	
419	// Per-insn tick for BBV-emit mode. udata is the bb_id (1-based) cast to
420	// pointer; that mapping is stable across calls because bbv_emit_assign_id
421	// is hashed by TB-start PC. The tick attributes one insn to the bb_id and
422	// flushes a slice row when the per-slice counter saturates.
423	static void on_bbv_tick(unsigned int vcpu_idx, void *udata)
424	{
425	    (void) vcpu_idx;
426	    uint64_t bb_id = (uint64_t) GPOINTER_TO_UINT(udata);
427	    bbv_emit_tick(bbv_emit, bb_id);
428	}
429	
430	// Per-insn tick for slice-consume mode (F11). Counts insns into the
431	// slice accumulator; on each slice boundary increments slice_consume_idx
432	// and resets the accumulator. Once slice_consume_idx exceeds the target
433	// slice index, drains via on_handoff at that same insn boundary. udata
434	// is the per-insn HandoffSite (allocated at translation time) so the
435	// post-trigger PC reaches on_handoff lag-free.
436	static void on_slice_consume_tick(unsigned int vcpu_idx, void *udata)
437	{
438	    if (++slice_consume_acc < bbv_slice_target) return;
439	    slice_consume_acc = 0;
440	    if (slice_consume_idx++ < slice_at_target) return;
441	    // After the post-increment above, slice_consume_idx == slice_at_target+1
442	    // (the count of fully retired slices). Log so the e2e test can verify
443	    // drain timing without relying on minstret (which is a cycle-counter
444	    // proxy on andes-ax45mpv and does not track plugin-counted insns).
445	    fprintf(stderr,
446	            "hybrid_handoff: slice-consume drain (idx=%" PRIu64
447	            " target=%" PRIu64 ")\n",
448	            slice_consume_idx, slice_at_target);
449	    on_handoff_boundary(vcpu_idx, udata);
450	}
