452	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
453	{
454	    (void) id;
455	    size_t n = qemu_plugin_tb_n_insns(tb);
456	
457	    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
458	    // TB-start vaddr). Same id is shared by every insn in the TB.
459	    uint64_t bb_id = 0;
460	    if (bbv_mode && n > 0) {
461	        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
462	        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
463	    }
464	
465	    for (size_t i = 0; i < n; i++) {
466	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
467	
468	        // F14 count tick: registered FIRST so the count is incremented
469	        // before any trigger callback can call exit(200). NO_REGS keeps
470	        // the per-insn cost minimal (a single uint64 add).
471	        if (drain_at_exit_mode) {
472	            qemu_plugin_register_vcpu_insn_exec_cb(
473	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
474	        }
475	
476	        // BBV callback is registered BEFORE icount so that if both modes
477	        // fire on the same insn (icount target == slice multiple), the
478	        // slice row is emitted before exit(200) is called.
479	        if (bbv_mode) {
480	            qemu_plugin_register_vcpu_insn_exec_cb(
481	                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
482	                GUINT_TO_POINTER((guint) bb_id));
483	        }
484	
485	        // Slice-consume callback (F11). Registered after BBV so a BBV
486	        // row at the same boundary is flushed first; ordering vs icount
487	        // is irrelevant (both drain).
488	        if (slice_consume_mode) {
489	            HandoffSite *site = g_new0(HandoffSite, 1);
490	            site->kind  = HYBRID_HANDOFF_ENTER;
491	            site->vaddr = qemu_plugin_insn_vaddr(insn);
492	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
493	            qemu_plugin_register_vcpu_insn_exec_cb(
494	                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
495	        }
496	
497	        if (icount_mode) {
498	            HandoffSite *site = g_new0(HandoffSite, 1);
499	            site->kind  = HYBRID_HANDOFF_ENTER;
500	            site->vaddr = qemu_plugin_insn_vaddr(insn);
501	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
502	            qemu_plugin_register_vcpu_insn_exec_cb(
503	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
504	        }
505	
506	        if (pc_mode) {
507	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
508	            // boundary (on_handoff_boundary), so the insn size is recorded
509	            // only for completeness.
510	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
511	            HandoffSite *site = g_new0(HandoffSite, 1);
512	            site->kind  = HYBRID_HANDOFF_ENTER;
513	            site->vaddr = qemu_plugin_insn_vaddr(insn);
514	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
515	            qemu_plugin_register_vcpu_insn_exec_cb(
516	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
517	            continue;
518	        }
519	
520	        // Marker-trigger mode (default).
521	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
522	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
523	        // exact, not an approximation.
524	        size_t sz = qemu_plugin_insn_size(insn);
525	        if (sz != 4) continue;
526	        uint32_t raw = 0;
527	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
528	            continue;
529	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
530	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
531	        HandoffSite *site = g_new0(HandoffSite, 1);
532	        site->kind  = kind;
533	        site->vaddr = qemu_plugin_insn_vaddr(insn);
534	        site->size  = (uint32_t) sz;
535	        qemu_plugin_register_vcpu_insn_exec_cb(
536	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
537	    }
538	}
