540	QEMU_PLUGIN_EXPORT int qemu_plugin_install(qemu_plugin_id_t id,
541	                                           const qemu_info_t *info,
542	                                           int argc, char **argv)
543	{
544	    (void) info;
545	    for (int i = 0; i < argc; i++) {
546	        g_auto(GStrv) tok = g_strsplit(argv[i], "=", 2);
547	        if (g_strcmp0(tok[0], "outfile") == 0 && tok[1]) {
548	            outfile_path = g_strdup(tok[1]);
549	        } else if (g_strcmp0(tok[0], "enter_pc") == 0 && tok[1]) {
550	            char *endp = NULL;
551	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
552	            if (!endp || *endp != '\0') {
553	                fprintf(stderr, "hybrid_handoff: invalid enter_pc=%s\n",
554	                        tok[1]);
555	                return -1;
556	            }
557	            enter_pc_arg = (uint64_t) v;
558	            pc_mode = 1;
559	        } else if (g_strcmp0(tok[0], "icount") == 0 && tok[1]) {
560	            char *endp = NULL;
561	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
562	            if (!endp || *endp != '\0' || v == 0) {
563	                fprintf(stderr, "hybrid_handoff: invalid icount=%s\n",
564	                        tok[1]);
565	                return -1;
566	            }
567	            icount_target = (uint64_t) v;
568	            icount_mode = 1;
569	        } else if (g_strcmp0(tok[0], "bbv_out") == 0 && tok[1]) {
570	            bbv_out_path = g_strdup(tok[1]);
571	            bbv_mode = 1;
572	        } else if (g_strcmp0(tok[0], "slice") == 0 && tok[1]) {
573	            char *endp = NULL;
574	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
575	            if (!endp || *endp != '\0' || v == 0) {
576	                fprintf(stderr, "hybrid_handoff: invalid slice=%s\n",
577	                        tok[1]);
578	                return -1;
579	            }
580	            bbv_slice_target = (uint64_t) v;
581	        } else if (g_strcmp0(tok[0], "slice_at") == 0 && tok[1]) {
582	            char *endp = NULL;
583	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
584	            if (!endp || *endp != '\0') {
585	                fprintf(stderr, "hybrid_handoff: invalid slice_at=%s\n",
586	                        tok[1]);
587	                return -1;
588	            }
589	            slice_at_target = (uint64_t) v;
590	            slice_consume_mode = 1;
591	        } else if (g_strcmp0(tok[0], "drain_at_exit") == 0 && tok[1]) {
592	            // F14: any non-zero value enables. "1" is the canonical form
593	            // hsim emits; other ints (incl. negatives parsed as huge unsigned)
594	            // also enable -- the flag is a binary switch, not a count.
595	            char *endp = NULL;
596	            unsigned long long v = g_ascii_strtoull(tok[1], &endp, 0);
597	            if (!endp || *endp != '\0') {
598	                fprintf(stderr, "hybrid_handoff: invalid drain_at_exit=%s\n",
599	                        tok[1]);
600	                return -1;
601	            }
602	            drain_at_exit_mode = (v != 0);
603	        } else {
604	            fprintf(stderr, "hybrid_handoff: unknown option: %s\n", argv[i]);
605	            return -1;
606	        }
607	    }
608	    if (!outfile_path) {
609	        fputs("hybrid_handoff: outfile=PATH is required\n", stderr);
610	        return -1;
611	    }
612	    if (pc_mode) {
613	        fprintf(stderr,
614	                "hybrid_handoff: PC-mode enter=0x%" PRIx64 "\n",
615	                enter_pc_arg);
616	    }
617	    if (icount_mode) {
618	        fprintf(stderr,
619	                "hybrid_handoff: icount-mode target=%" PRIu64 "\n",
620	                icount_target);
621	    }
622	    if (bbv_mode) {
623	        if (bbv_slice_target == 0) {
624	            fputs("hybrid_handoff: bbv_out= requires slice=N\n", stderr);
625	            return -1;
626	        }
627	        bbv_emit = bbv_emit_new(bbv_out_path, bbv_slice_target);
628	        if (!bbv_emit) {
629	            fprintf(stderr, "hybrid_handoff: failed to open bbv_out=%s\n",
630	                    bbv_out_path);
631	            return -1;
632	        }
633	        fprintf(stderr,
634	                "hybrid_handoff: bbv-mode out=%s slice=%" PRIu64 "\n",
635	                bbv_out_path, bbv_slice_target);
636	    }
637	    if (slice_consume_mode) {
638	        if (bbv_slice_target == 0) {
639	            fputs("hybrid_handoff: slice_at= requires slice=N\n", stderr);
640	            return -1;
641	        }
642	        fprintf(stderr,
643	                "hybrid_handoff: slice-consume mode slice=%" PRIu64
644	                " slice_at=%" PRIu64 "\n",
645	                bbv_slice_target, slice_at_target);
646	    }
647	    if (drain_at_exit_mode) {
648	        fputs("hybrid_handoff: drain-at-exit mode enabled\n", stderr);
649	        qemu_plugin_register_atexit_cb(id, on_atexit, NULL);
650	    }
651	
652	    vcpu_state = qemu_plugin_scoreboard_new(sizeof(VcpuRegs));
653	    qemu_plugin_register_vcpu_tb_trans_cb(id, vcpu_tb_trans);
654	    return 0;
655	}
